// Part-space → canvas mapping shared by the Windows and Linux renderers (macOS mirrors it in
// Sources/CatRenderer.swift, the web pet / workshop in renderer.js). The numbers come from shared/rig.json;
// tests/rig/reference.py is the reference implementation every port is checked against
// (bash scripts/check-rig.sh).
#pragma once
#include <algorithm>
#include <cmath>

namespace kurorig {

// <rig:generated> generated by scripts/gen-rig.py from shared/rig.json; edit that file, not this block
constexpr float CanvasWidth = 360.0f;
constexpr float CanvasHeight = 320.0f;
constexpr float SeatX = 184.0f;
constexpr float SeatY = 226.0f;
constexpr float YawPerUnit = 0.5f;
constexpr float PitchPerUnit = 0.36f;
constexpr float MaxHeadYaw = 1.0f;
constexpr float HeadShiftPerYaw = 7.5f;
constexpr float DomeRadiusX = 46.0f;
constexpr float DomeRadiusY = 40.0f;
constexpr float DomeDepth = 29.6f;
constexpr float PlaneDepth = 27.5f;
constexpr float LieSquash = 0.42f;
constexpr float SquashWiden = 0.55f;
constexpr float LieWiden = 0.03f;
// </rig:generated>

struct Vec2 { float x, y; };

// Depth of a head-space point on the skin's head surface. `whiteSurface` is the flatter smoothstep falloff the
// built-in milk / bib marks use; skins never set it.
inline float headDepth(float x, float y, bool dome, bool whiteSurface = false) {
    if (!dome) return PlaneDepth;
    float radius = std::max(0.0f, 1.0f - x * x / (DomeRadiusX * DomeRadiusX) - y * y / (DomeRadiusY * DomeRadiusY));
    float surface = whiteSurface ? radius * radius * (3.0f - 2.0f * radius) : std::sqrt(radius);
    return DomeDepth * surface;
}

// Rotate (x, y, z) by yaw (around y) then pitch (around x); orthographic, so only x and y come back.
inline Vec2 projectHead3D(float x, float y, float z, float yawRad, float pitchRad) {
    float cy = std::cos(yawRad), sy = std::sin(yawRad);
    float x1 = x * cy + z * sy;
    float z1 = -x * sy + z * cy;
    float cp = std::cos(pitchRad), sp = std::sin(pitchRad);
    float y2 = y * cp + z1 * sp;
    return { x1, y2 };
}

// `head` / `skull` space → canvas. skull skips the 3D turn (it only follows tilt and the head centre).
inline Vec2 headPoint(float x, float y, bool skull, bool dome, float headScale,
                      float headYaw, float headPitch, float headTilt, float headX, float headY,
                      bool whiteSurface = false) {
    Vec2 q = skull ? Vec2{ x, y }
                   : projectHead3D(x, y, headDepth(x, y, dome, whiteSurface), headYaw * YawPerUnit, headPitch * PitchPerUnit);
    q.x *= headScale; q.y *= headScale;
    float c = std::cos(headTilt), s = std::sin(headTilt);
    return { headX + q.x * c - q.y * s, headY + q.x * s + q.y * c };
}

// `body` space → canvas: squash / lie-down deformation, then the body tilt around the seat anchor.
inline Vec2 bodyPoint(float x, float y, float bodyWidth, float bodySquash, float lieIntensity, float bodyTilt,
                      float seatX, float seatY) {
    float lie = std::clamp(lieIntensity, 0.0f, 1.0f);
    float lieS = lie * lie * (3.0f - 2.0f * lie);
    float sy = bodySquash * (1.0f - lieS * LieSquash);
    float sx = (1.0f + (1.0f - bodySquash) * SquashWiden) * (1.0f + lieS * LieWiden);
    float c = std::cos(bodyTilt), s = std::sin(bodyTilt);
    return { seatX + x * bodyWidth * sx * c - y * sy * s, seatY + x * bodyWidth * sx * s + y * sy * c };
}

} // namespace kurorig
